def choose_move(observation):
    # Defensive defaults
    x = observation.get("position_x", 0)
    y = observation.get("position_y", 0)

    # Attempt to read a simple, robust signal from a few possible observation fields
    # If the environment provides resource targets, pursue them.
    target = None
    if isinstance(observation, dict):
        # Common field names across tasks
        for key in ("resource_target", "resource", "target"):
            if key in observation:
                target = observation.get(key)
                break

        # If there's a visible opponent for pursuit/evasion
        opponent = observation.get("opponent_position")
        if opponent is None:
            opponent = observation.get("pursuer_position")

        # If there is a territory control objective (e.g., flag or territory_center)
        territory = observation.get("territory_center") or observation.get("flag_position")

        # Basic heuristic priorities:
        # 1) Move toward a resource/target if available
        if target is not None:
            try:
                tx, ty = target.get("x", None), target.get("y", None)
                if tx is not None and ty is not None:
                    dx = int((tx - x) / max(1, abs(tx - x)))
                    dy = int((ty - y) / max(1, abs(ty - y)))
                    if dx in (-1, 0, 1) and dy in (-1, 0, 1):
                        return [dx, dy]
            except Exception:
                pass

        # 2) If pursuing an opponent, move toward them if safe
        if opponent is not None:
            try:
                ox, oy = opponent.get("x", 0), opponent.get("y", 0)
                dx = int((ox - x) / max(1, abs(ox - x)))
                dy = int((oy - y) / max(1, abs(oy - y)))
                if dx in (-1, 0, 1) and dy in (-1, 0, 1):
                    return [dx, dy]
            except Exception:
                pass

        # 3) If a territory center/flag is given, move toward it
        if territory is not None:
            try:
                tx, ty = territory.get("x", None), territory.get("y", None)
                if tx is not None and ty is not None:
                    dx = int((tx - x) / max(1, abs(tx - x)))
                    dy = int((ty - y) / max(1, abs(ty - y)))
                    if dx in (-1, 0, 1) and dy in (-1, 0, 1):
                        return [dx, dy]
            except Exception:
                pass

    # Fallback: stay within grid by moving to reduce distance to origin (0,0)
    dx = 0 if x == 0 else (-1 if x > 0 else 1)
    dy = 0 if y == 0 else (-1 if y > 0 else 1)
    if dx in (-1, 0, 1) and dy in (-1, 0, 1):
        return [dx, dy]

    return [0, 0]

